use std::collections::HashSet;
fn build_charset(spec: &str) -> Result<Vec<char>, String> {
    let mut set = Vec::new();
    for ch in spec.chars() {
        match ch {
            'l' => set.extend('a'..='z'),
            'u' => set.extend('A'..='Z'),
            'd' => set.extend('0'..='9'),
            'h' => {
                set.extend('0'..='9');
                set.extend('a'..='f');
            },
            'H' => {
                set.extend('0'..='9');
                set.extend('A'..='F');
            },
            's' => {
                // space and symbols: we observed 33 chars
                set.extend(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".chars());
            },
            _ => return Err(format!("Unknown charset option '{}'", ch)),
        }
    }
    Ok(set)
}

fn main() {
    for spec in ["l","u","d","h","H","s","lud","x","ll"] {
        match build_charset(spec) {
            Ok(v) => {
                let mut sorted: Vec<char> = v.into_iter().collect::<HashSet<_>>().into_iter().collect();
                sorted.sort();
                println!("{} -> {} chars sorted {:?}", spec, sorted.len(), sorted.iter().collect::<String>());
                // Also show unsorted
                let v2 = build_charset(spec).unwrap();
                let mut uniq = HashSet::new();
                let mut ordered = Vec::new();
                for c in v2 {
                    if uniq.insert(c) { ordered.push(c); }
                }
                println!("  ordered uniq {:?}", ordered.iter().collect::<String>());
            },
            Err(e) => println!("{} err {}", spec, e),
        }
    }
    // test charsetFile combined?
}
