fn main() {
    let spec="lud";
    let charset = {
        let mut set = Vec::new();
        for ch in spec.chars() {
            match ch {
                'l' => set.extend('a'..='z'),
                'u' => set.extend('A'..='Z'),
                'd' => set.extend('0'..='9'),
                'h' => { set.extend('0'..='9'); set.extend('a'..='f'); },
                'H' => { set.extend('0'..='9'); set.extend('A'..='F'); },
                's' => set.extend(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".chars()),
                _ => panic!("unknown"),
            }
        }
        set
    };
    // Deduplicate then sort
    let mut uniq: std::collections::HashSet<char> = std::collections::HashSet::new();
    let mut dedup: Vec<char> = Vec::new();
    for c in charset {
        if uniq.insert(c) { dedup.push(c); }
    }
