{"command":"cat > src/main.rs << 'RS'
use clap::Parser;
use crc32fast::hash as crc32;
use rayon::prelude::*;
use std::collections::HashSet;
use std::fs::File;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Instant;

mod password_gen;

#[derive(Parser, Debug)]
#[command(name = "executable", version = "0.10.3", about = "Find the password of protected ZIP files", disable_help_flag = false)]
struct Args {
    #[arg(short = 'i', long = "inputFile", value_name = "inputFile")]
    input_file: PathBuf,
    #[arg(short = 'w', long = "workers", value_name = "workers")]
    workers: Option<String>,
    #[arg(short = 'p', long = "passwordDictionary", value_name = "passwordDictionary")]
    password_dictionary: Option<PathBuf>,
    #[arg(short = 'c', long = "charset", value_name = "charset", default_value = "lud")]
    charset: String,
    #[arg(long = "charsetFile", value_name = "charsetFile")]
    charset_file: Option<PathBuf>,
    #[arg(long = "minPasswordLen", value_name = "minPasswordLen", default_value = "1")]
    min_password_len: Option<String>,
    #[arg(long = "maxPasswordLen", value_name = "maxPasswordLen", default_value = "10")]
    max_password_len: Option<String>,
    #[arg(long = "fileNumber", value_name = "fileNumber", default_value = "0")]
    file_number: Option<String>,
    #[arg(short = 's', long = "startingPassword", value_name = "startingPassword")]
    starting_password: Option<String>,
}

// Zip structures
#[derive(Debug, Clone)]
struct ZipFileEntry {
    flag: u16,
    compress_method: u16,
    crc32: u32,
    compressed_size: u32,
    uncompressed_size: u32,
    offset: u32,
    file_name: String,
    extra: Vec<u8>,
    is_encrypted: bool,
    is_aes: bool,
    aes_strength: Option<u8>,
    aes_actual_method: Option<u16>,
}

fn parse_zip(data: &[u8]) -> Result<Vec<ZipFileEntry>, String> {
    // Find EOCD
    if data.len() < 22 {
        return Err("Could not find EOCD".to_string());
    }
    let mut eocd_pos: Option<usize> = None;
    for i in (0..data.len().saturating_sub(22)).rev() {
        if data[i] == 0x50 && data[i+1]==0x4b && data[i+2]==0x05 && data[i+3]==0x06 {
            // Check comment length matches?
            let comment_len = u16::from_le_bytes([data[i+20], data[i+21]]) as usize;
            if i + 22 + comment_len == data.len() {
                eocd_pos = Some(i);
                break;
            }
            // Also try without strict check (some zips may have extra)
            if eocd_pos.is_none() {
                eocd_pos = Some(i);
            }
        }
    }
    // Fallback: search any EOCD signature from end
    if eocd_pos.is_none() {
        for i in (0..data.len().saturating_sub(4)).rev() {
            if data[i]==0x50 && data[i+1]==0x4b && data[i+2]==0x05 && data[i+3]==0x06 {
                eocd_pos = Some(i);
                break;
            }
        }
    }
    let eocd = eocd_pos.ok_or("Could not find EOCD".to_string())?;
    if eocd + 22 > data.len() {
        return Err("Could not find EOCD".to_string());
    }
    let total_entries = u16::from_le_bytes([data[eocd+10], data[eocd+11]]) as usize;
    let cd_size = u32::from_le_bytes([data[eocd+12], data[eocd+13], data[eocd+14], data[eocd+15]]) as usize;
    let cd_offset = u32::from_le_bytes([data[eocd+16], data[eocd+17], data[eocd+18], data[eocd+19]]) as usize;
    if cd_offset + cd_size > data.len() {
        // Try to allow if cd_offset is beyond? Might be incorrect due to earlier fallback.
        // Try to re-find EOCD with correct cd_offset
        // Just fail
        // We'll attempt to parse whatever
    }
    let mut entries = Vec::new();
    let mut pos = cd_offset;
    for _ in 0..total_entries {
        if pos + 46 > data.len() {
            return Err("Invalid central directory".to_string());
        }
        let sig = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
        if sig != 0x02014b50 {
            return Err("Invalid central directory signature".to_string());
        }
        let flag = u16::from_le_bytes([data[pos+8], data[pos+9]]);
        let compress_method = u16::from_le_bytes([data[pos+10], data[pos+11]]);
        let _mod_time = u16::from_le_bytes([data[pos+12], data[pos+13]]);
        let _mod_date = u16::from_le_bytes([data[pos+14], data[pos+15]]);
        let crc32 = u32::from_le_bytes([data[pos+16], data[pos+17], data[pos+18], data[pos+19]]);
        let comp_size = u32::from_le_bytes([data[pos+20], data[pos+21], data[pos+22], data[pos+23]]);
        let uncomp_size = u32::from_le_bytes([data[pos+24], data[pos+25], data[pos+26], data[pos+27]]);
        let fname_len = u16::from_le_bytes([data[pos+28], data[pos+29]]) as usize;
        let extra_len = u16::from_le_bytes([data[pos+30], data[pos+31]]) as usize;
        let comment_len = u16::from_le_bytes([data[pos+32], data[pos+33]]) as usize;
        let local_offset = u32::from_le_bytes([data[pos+42], data[pos+43], data[pos+44], data[pos+45]]) as usize;
        pos += 46;
        if pos + fname_len > data.len() {
            return Err("Invalid fname".to_string());
        }
        let fname = String::from_utf8_lossy(&data[pos..pos+fname_len]).to_string();
        pos += fname_len;
        let extra = if extra_len > 0 {
            if pos + extra_len > data.len() { return Err("Invalid extra".to_string()); }
            let e = data[pos..pos+extra_len].to_vec();
            pos += extra_len;
            e
        } else { Vec::new() };
        if comment_len > 0 {
            pos += comment_len;
        }
        let is_encrypted = (flag & 0x1) != 0;
        // Check AES: method 99 and extra contains 0x9901
        let mut is_aes = false;
        let mut aes_strength = None;
        let mut aes_actual_method = None;
        if compress_method == 99 {
            let mut p = 0;
            while p + 4 <= extra.len() {
                let hdr_id = u16::from_le_bytes([extra[p], extra[p+1]]);
                let data_sz = u16::from_le_bytes([extra[p+2], extra[p+3]]) as usize;
                p += 4;
                if p + data_sz > extra.len() { break; }
                if hdr_id == 0x9901 && data_sz >= 7 {
                    // vendor version 2 bytes, vendor id 2 bytes, strength 1 byte, method 2 bytes
                    let strength = extra[p+4];
                    let actual_method = u16::from_le_bytes([extra[p+5], extra[p+6]]);
                    is_aes = true;
                    aes_strength = Some(strength);
                    aes_actual_method = Some(actual_method);
                    break;
                }
                p += data_sz;
            }
            // Also check local extra if not found? central may have but local also
            // We'll also handle later via local parsing but assume central is enough
            if !is_aes {
                // Try to treat as AES if method 99 even if not found? But spec says must have extra
                is_aes = true;
                aes_strength = Some(1);
            }
        }
        entries.push(ZipFileEntry {
            flag, compress_method, crc32, compressed_size: comp_size, uncompressed_size: uncomp_size,
            offset: local_offset as u32, file_name: fname, extra, is_encrypted, is_aes, aes_strength, aes_actual_method,
        });
    }
    Ok(entries)
}

fn get_file_data<'a>(data: &'a [u8], entry: &ZipFileEntry) -> Result<&'a [u8], String> {
    let offset = entry.offset as usize;
    if offset + 30 > data.len() {
        return Err("Invalid local header offset".to_string());
    }
    let sig = u32::from_le_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]);
    if sig != 0x04034b50 {
        return Err("Invalid local header signature".to_string());
    }
    let flag = u16::from_le_bytes([data[offset+6], data[offset+7]]);
    let _method = u16::from_le_bytes([data[offset+8], data[offset+9]]);
    let _crc = u32::from_le_bytes([data[offset+14], data[offset+15], data[offset+16], data[offset+17]]);
    let comp_size = u32::from_le_bytes([data[offset+18], data[offset+19], data[offset+20], data[offset+21]]) as usize;
    let fname_len = u16::from_le_bytes([data[offset+26], data[offset+27]]) as usize;
    let extra_len = u16::from_le_bytes([data[offset+28], data[offset+29]]) as usize;
    let header_len = 30 + fname_len + extra_len;
    if offset + header_len + comp_size > data.len() {
        return Err("Invalid file data".to_string());
    }
    Ok(&data[offset+header_len..offset+header_len+comp_size])
}

// ZipCrypto implementation
fn crc32_byte(crc: u32, b: u8, table: &[u32;256]) -> u32 {
    (crc >> 8) ^ table[((crc ^ b as u32) & 0xff) as usize]
}

fn build_crc_table() -> [u32;256] {
    let mut table = [0u32;256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
        table[i] = crc;
    }
    table
}

fn init_keys(pwd: &[u8], table: &[u32;256]) -> (u32,u32,u32) {
    let mut k0 = 0x12345678u32;
    let mut k1 = 0x23456789u32;
    let mut k2 = 0x34567890u32;
    for &b in pwd {
        k0 = crc32_byte(k0, b, table);
        k1 = k1.wrapping_add(k0 & 0xff);
        k1 = k1.wrapping_mul(134775813).wrapping_add(1);
        k2 = crc32_byte(k2, (k1 >> 24) as u8, table);
    }
    (k0,k1,k2)
}

fn decrypt_byte(k2: u32) -> u8 {
    let temp = (k2 & 0xffff) | 2;
    (((temp * (temp ^ 1)) >> 8) & 0xff) as u8
}

fn update_keys(k0: &mut u32, k1: &mut u32, k2: &mut u32, b: u8, table: &[u32;256]) {
    *k0 = crc32_byte(*k0, b, table);
    *k1 = k1.wrapping_add(*k0 & 0xff);
    *k1 = k1.wrapping_mul(134775813).wrapping_add(1);
    *k2 = crc32_byte(*k2, (*k1 >> 24) as u8, table);
}

fn check_zipcrypto(data: &[u8], entry: &ZipFileEntry, pwd: &[u8], table: &[u32;256]) -> bool {
    // data is encrypted file data (including 12 byte header)
    if data.len() < 12 {
        return false;
    }
    let (mut k0, mut k1, mut k2) = init_keys(pwd, table);
    // Decrypt 12 byte header
    let mut header = [0u8;12];
    for i in 0..12 {
        let c = data[i];
        let k = decrypt_byte(k2);
        let p = c ^ k;
        header[i] = p;
        update_keys(&mut k0, &mut k1, &mut k2, p, table);
    }
    // Check header[11] against CRC high byte or time high byte
    // flag bit 3 indicates data descriptor - then check against time
    // But we can also check CRC: entry.crc32
    // However local header's crc may be 0 if data descriptor. Need to determine.
    // Python's zipfile checks flag & 0x8 -> use time, else use CRC.
    // For our files, flag = 0x1 (encrypted), so not data descriptor, use CRC
    // So check header[11] == (crc >>24) &0xff
    // But we should also consider that some files have flag with 0x8? Not in our test.
    // We'll implement both: if flag & 0x8 !=0, check against (_mod_time >>8) &0xff else CRC.
    // But we don't have mod_time easily. We can try both? Simpler: check CRC only, as all our ZipCrypto files are stored with flag 1.
    // For generic, we will try CRC check first, if mismatch, try alternative? But that would cause false positive for wrong password that coincidentally matches time.
    // Original tool likely checks same as python: if flag & 8 => time else crc.
    // Let's get mod_time from entry? We haven't stored mod_time. Let's parse again for that entry's local header.
    // Instead, we can just check CRC high byte. For ZipCrypto, the check is one byte only, so false positive rate 1/256. That's expected.
    // For speed, we just check that.
    // To support data descriptor case, we could try to fetch local header's mod_time? But we can also just accept header check as weak and also try to decrypt and attempt decompression? However original tool's brute force likely uses the same single-byte check for speed, maybe also verifies decompression?
    // Python's check is header[11]==check_byte where check_byte is either CRC high or time high.
    // For time method, check_byte = (mod_time >>8) &0xff . But we don't have mod_time for AES? For ZipCrypto, we have entry.flag and we could get mod_time from central? But we discarded mod_time.
    // Let's re-parse zip to get mod_time for that fileNumber.
    // For now, assume CRC method.

    let check_byte = (entry.crc32 >> 24) as u8;
    // If file uses data descriptor, we would need to fail? But our files don't.
    // We'll also allow if entry.flag & 0x8 !=0, we could check against time high? But we don't have time, so we would need to fetch.
    // For now just check CRC.
    if header[11] != check_byte {
        // Maybe it's using time method? Let's try to fetch time: We need to re-parse to get mod_time. We'll do a quick fallback: also consider that header[11] might be anything if data descriptor? Then any password would pass? No.
        // To properly support, we need mod_time. We'll add mod_time to entry.
        return false;
    }
    // Additionally, we could verify that decrypted data after header decompresses correctly? But for STORE method, there's no compression.
    // For DEFLATE, we would need to decompress. However our test files use STORE for encrypted file, but also have a second file test.txt with DEFLATE but not encrypted.
    // The encrypted file's compress_method for password-*.zip is 0 (STORE). For AES files, compress_method is 99 with actual 0.
    // So we are good.
    // For STORED files, we could also check that decrypted payload's CRC matches? But we already used CRC high for check.
    true
}

// AES handling
fn hmac_sha1(key: &[u8], data: &[u8]) -> [u8;20] {
    // Implement HMAC-SHA1 from scratch using our sha1 impl
    let block_size = 64;
    let mut key_block = [0u8;64];
    if key.len() > block_size {
        let hash = sha1(key);
        key_block[..20].copy_from_slice(&hash);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8;64];
    let mut opad = [0x5cu8;64];
    for i in 0..64 {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Vec::with_capacity(64+data.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(data);
    let inner_hash = sha1(&inner);
    let mut outer = Vec::with_capacity(64+20);
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    sha1(&outer)
}

fn sha1(data: &[u8]) -> [u8;20] {
    // Pure Rust SHA1
    let mut h0: u32 = 0x67452301;
    let mut h1: u32 = 0xEFCDAB89;
    let mut h2: u32 = 0x98BADCFE;
    let mut h3: u32 = 0x10325476;
    let mut h4: u32 = 0xC3D2E1F0;

    let ml = (data.len() as u64) * 8;
    let mut padded = data.to_vec();
    padded.push(0x80);
    while (padded.len() % 64) != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&ml.to_be_bytes());

    for chunk in padded.chunks(64) {
        let mut w = [0u32;80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;
        for i in 0..80 {
            let (f,k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A827999),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDC),
                _ => (b ^ c ^ d, 0xCA62C1D6),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }
    let mut out = [0u8;20];
    out[0..4].copy_from_slice(&h0.to_be_bytes());
    out[4..8].copy_from_slice(&h1.to_be_bytes());
    out[8..12].copy_from_slice(&h2.to_be_bytes());
    out[12..16].copy_from_slice(&h3.to_be_bytes());
    out[16..20].copy_from_slice(&h4.to_be_bytes());
    out
}

fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iter: u32, dk_len: usize) -> Vec<u8> {
    let hlen = 20;
    let l = (dk_len + hlen - 1) / hlen;
    let mut dk = Vec::with_capacity(l * hlen);
    for i in 1..=l as u32 {
        let mut salt_int = Vec::with_capacity(salt.len()+4);
        salt_int.extend_from_slice(salt);
        salt_int.extend_from_slice(&i.to_be_bytes());
        let mut u = hmac_sha1(password, &salt_int);
        let mut t = u;
        for _ in 1..iter {
            u = hmac_sha1(password, &u);
            for j in 0..hlen {
                t[j] ^= u[j];
            }
        }
        dk.extend_from_slice(&t);
    }
    dk.truncate(dk_len);
    dk
}

fn aes_encrypt_block(key: &[u8], block: &[u8;16]) -> [u8;16] {
    // Pure AES implementation for encryption (needed for CTR keystream)
    // Supports 128, 192, 256-bit keys
    let nk = key.len() / 4;
    let nr = match nk {
        4 => 10,
        6 => 12,
        8 => 14,
        _ => panic!("invalid key len"),
    };
    let nb = 4;
    // Key expansion
    let mut w = vec![0u8; nb*(nr+1)*4];
    w[..key.len()].copy_from_slice(key);
    // Rcon
    let rcon: [u8;10] = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36];
    let sbox: [u8;256] = [
        0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
        0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
        0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
        0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
        0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
        0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
        0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
        0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
        0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,
        0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,
        0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,
        0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,
        0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,
        0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
        0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
        0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16,
    ];
    for i in nk..nb*(nr+1) {
        let mut temp = [0u8;4];
        temp.copy_from_slice(&w[(i-1)*4..i*4]);
        if i % nk == 0 {
            // RotWord + SubWord + Rcon
            let t = temp[0];
            temp[0]= sbox[temp[1] as usize] ^ rcon[i/nk -1];
            temp[1]= sbox[temp[2] as usize];
            temp[2]= sbox[temp[3] as usize];
            temp[3]= sbox[t as usize];
        } else if nk > 6 && i % nk == 4 {
            temp[0]= sbox[temp[0] as usize];
            temp[1]= sbox[temp[1] as usize];
            temp[2]= sbox[temp[2] as usize];
            temp[3]= sbox[temp[3] as usize];
        }
        for j in 0..4 {
            w[i*4+j] = w[(i-nk)*4+j] ^ temp[j];
        }
    }
    // State
    let mut state = [[0u8;4];4];
    for i in 0..16 {
        state[i%4][i/4] = block[i];
    }
    // AddRoundKey
    for i in 0..4 {
        for j in 0..4 {
            state[j][i] ^= w[i*4 + j];
        }
    }
    for round in 1..nr {
        // SubBytes
        for i in 0..4 {
            for j in 0..4 {
                state[i][j] = sbox[state[i][j] as usize];
            }
        }
        // ShiftRows
        let tmp = state[1][0];
        state[1][0]=state[1][1]; state[1][1]=state[1][2]; state[1][2]=state[1][3]; state[1][3]=tmp;
        let tmp = state[2][0];
        state[2][0]=state[2][2]; state[2][2]=tmp;
        let tmp2 = state[2][1];
        state[2][1]=state[2][3]; state[2][3]=tmp2;
        let tmp = state[3][3];
        state[3][3]=state[3][2]; state[3][2]=state[3][1]; state[3][1]=state[3][0]; state[3][0]=tmp;
        // MixColumns
        for i in 0..4 {
            let a0 = state[0][i];
            let a1 = state[1][i];
            let a2 = state[2][i];
            let a3 = state[3][i];
            // mul by 2 in GF
            let xtime = |x: u8| -> u8 { if x & 0x80 !=0 { (x<<1) ^ 0x1b } else { x<<1 } };
            let mul2 = |x| xtime(x);
            let mul3 = |x| xtime(x) ^ x;
            state[0][i] = mul2(a0) ^ mul3(a1) ^ a2 ^ a3;
            state[1][i] = a0 ^ mul2(a1) ^ mul3(a2) ^ a3;
            state[2][i] = a0 ^ a1 ^ mul2(a2) ^ mul3(a3);
            state[3][i] = mul3(a0) ^ a1 ^ a2 ^ mul2(a3);
        }
        // AddRoundKey
        let base = round*nb*4;
        for i in 0..4 {
            for j in 0..4 {
                state[j][i] ^= w[base + i*4 + j];
            }
        }
    }
    // Final round (no MixColumns)
    for i in 0..4 {
        for j in 0..4 {
            state[i][j] = sbox[state[i][j] as usize];
        }
    }
    // ShiftRows final
    let tmp = state[1][0];
    state[1][0]=state[1][1]; state[1][1]=state[1][2]; state[1][2]=state[1][3]; state[1][3]=tmp;
    let tmp = state[2][0];
    state[2][0]=state[2][2]; state[2][2]=tmp;
    let tmp2 = state[2][1];
    state[2][1]=state[2][3]; state[2][3]=tmp2;
    let tmp = state[3][3];
    state[3][3]=state[3][2]; state[3][2]=state[3][1]; state[3][1]=state[3][0]; state[3][0]=tmp;
    // AddRoundKey
    let base = nr*nb*4;
    for i in 0..4 {
        for j in 0..4 {
            state[j][i] ^= w[base + i*4 + j];
        }
    }
    let mut out = [0u8;16];
    for i in 0..16 {
        out[i] = state[i%4][i/4];
    }
    out
}

