fn check_aes(data: &[u8], entry: &ZipFileEntry, pwd: &[u8]) -> bool {
    // data is file_data from local header (salt+pwv+enc+auth)
    // Determine AES params
    let method_strength = entry.aes_strength.unwrap_or(1);
    let salt_len = match method_strength {
        1 => 8,
        2 => 12,
        3 => 16,
        _ => 8,
    };
    let key_len = match method_strength {
        1 => 16,
        2 => 24,
        3 => 32,
        _ => 16,
    };
    if data.len() < salt_len + 2 + 10 {
        return false;
    }
    let salt = &data[..salt_len];
    let pwv = &data[salt_len..salt_len+2];
    // enc is data[salt_len+2 .. len-10]
    // auth is last 10
    // Derive keys
    let dk = pbkdf2_hmac_sha1(pwd, salt, 1000, key_len*2+2);
    let _aes_key = &dk[..key_len];
    let _hmac_key = &dk[key_len..key_len*2];
    let derived_pwv = &dk[key_len*2..key_len*2+2];
    if derived_pwv != pwv {
        return false;
    }
    // For speed, we only check pwv, not HMAC. But to avoid false positives with 2-byte check, we also check HMAC?
    // However original tool's AES brute force may only check pwv (2 bytes) for speed, but to be thorough we should check HMAC as well (10 bytes). Let's check HMAC if we have time.
    // For now, just pwv is enough to identify password (2 bytes has 1/65536 false positive). But we can also verify HMAC to reduce false positives.
    // Let's also verify HMAC.
    let enc_data = &data[salt_len+2..data.len()-10];
    let auth = &data[data.len()-10..];
    let hmac_calc = hmac_sha1(_hmac_key, enc_data);
    if hmac_calc[..10] != auth[..] {
        return false;
    }
    true
}

fn check_password(data: &[u8], entries: &[ZipFileEntry], file_number: usize, pwd: &[u8], table: &[u32;256]) -> bool {
    if file_number >= entries.len() {
        return false;
    }
    let entry = &entries[file_number];
    if !entry.is_encrypted {
        return false;
    }
    // Get file data
    let file_data = match get_file_data(data, entry) {
        Ok(d) => d,
        Err(_) => return false,
    };
    if entry.is_aes {
        check_aes(file_data, entry, pwd)
    } else {
        check_zipcrypto(file_data, entry, pwd, table)
    }
}

fn build_charset(spec: &str) -> Result<Vec<char>, String> {
    let mut chars = Vec::new();
    for ch in spec.chars() {
        match ch {
            'l' => chars.extend('a'..='z'),
            'u' => chars.extend('A'..='Z'),
            'd' => chars.extend('0'..='9'),
            'h' => {
                chars.extend('0'..='9');
                chars.extend('a'..='f');
            },
            'H' => {
                chars.extend('0'..='9');
                chars.extend('A'..='F');
            },
            's' => {
                chars.extend(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".chars());
            },
            _ => return Err(format!("Unknown charset option '{}'", ch)),
        }
    }
    // Dedup and sort
    let mut set = HashSet::new();
    let mut uniq = Vec::new();
    for c in chars {
        if set.insert(c) {
            uniq.push(c);
        }
    }
    uniq.sort();
    Ok(uniq)
}

fn charset_from_file(path: &PathBuf) -> Result<Vec<char>, String> {
    let data = std::fs::read(path).map_err(|_| format!("'charsetFile' does not exist"))?;
    // Read as bytes, convert to chars (assume utf8? original may read raw bytes including newline)
    // We'll treat each byte as char, including whitespace and newlines.
    // But original's panic suggests they treat charset as Vec<char> not bytes. Let's read as string lossily.
    let s = String::from_utf8_lossy(&data);
    let mut set = HashSet::new();
    let mut uniq = Vec::new();
    for c in s.chars() {
        if set.insert(c) {
            uniq.push(c);
        }
    }
    uniq.sort();
    Ok(uniq)
}

fn index_to_password(mut index: u128, charset: &[char], len: usize) -> String {
    // Convert index to base charset.len() representation, little endian? Need to match original order.
    // For sorted charset, mapping is index 0 -> first char repeated len times? Actually for length 2, index 0 = aa, 1=ab, 2=ba, 3=bb if charset sorted a,b and len 2.
    // That's base-N where most significant digit is first char.
    // So we need to convert index to base N with len digits, where digit 0 is most significant.
    // For le, index 0 = aa => digits [0,0], index 1=ab => [0,1], index2=ba => [1,0], index3=bb => [1,1]
    // That's standard base conversion where we fill from least significant.
    let n = charset.len() as u128;
    let mut chars = vec![' '; len];
    for i in (0..len).rev() {
        let digit = (index % n) as usize;
        chars[i] = charset[digit];
        index /= n;
    }
    chars.into_iter().collect()
}

fn password_to_index(pwd: &str, charset: &[char]) -> Option<u128> {
    let n = charset.len() as u128;
    let mut map = std::collections::HashMap::new();
    for (i,&c) in charset.iter().enumerate() {
        map.insert(c, i as u128);
    }
    let mut idx: u128 = 0;
    for ch in pwd.chars() {
        let digit = *map.get(&ch)? as u128;
        idx = idx * n + digit;
    }
    Some(idx)
}

fn total_combinations(charset_len: usize, min_len: usize, max_len: usize) -> u128 {
    let mut total = 0u128;
    for len in min_len..=max_len {
        let mut pow = 1u128;
        for _ in 0..len {
            pow = pow.saturating_mul(charset_len as u128);
            if pow > u128::MAX/2 { break; }
        }
        total = total.saturating_add(pow);
    }
    total
}

fn offset_for_len(charset_len: usize, min_len: usize, target_len: usize) -> u128 {
    let mut offset = 0u128;
    for len in min_len..target_len {
        let mut pow = 1u128;
        for _ in 0..len {
            pow *= charset_len as u128;
        }
        offset += pow;
    }
    offset
}

