                    }
                    remaining -= pow; // Wait earlier offset calculation was different: offset_for_len gives start offset, but here idx is global. We should compute len by subtracting offsets.
                    // Actually our earlier offset_for_len is for converting. For idx, we need to find len such that idx < offset+pow
                    // Simpler: iterate with offset
                }
                // Recompute correctly
                let mut len_found = min_len;
                let mut off = 0u128;
                let mut pow_for_len = 0u128;
                for len in min_len..=max_len {
                    pow_for_len = (n as usize).pow(len as u32) as u128;
                    if idx < off + pow_for_len {
                        len_found = len;
                        break;
                    }
                    off += pow_for_len;
