    for i in 0..4 {
        for j in 0..4 {
            state[j][i] ^= w[i*4 + j];
        }
    }
    for round in 1..nr {
        // SubBytes
        for i in 0..4 {
            for j in 0..4 {
                state[i][j] = sbox[state[i][j] as usize];
            }
        }
        // ShiftRows
        let tmp = state[1][0];
        state[1][0]=state[1][1]; state[1][1]=state[1][2]; state[1][2]=state[1][3]; state[1][3]=tmp;
        let tmp = state[2][0];
