        for i in 0..4 {
            let a0 = state[0][i];
            let a1 = state[1][i];
            let a2 = state[2][i];
            let a3 = state[3][i];
            // mul by 2 in GF
            let xtime = |x: u8| -> u8 { if x & 0x80 !=0 { (x<<1) ^ 0x1b } else { x<<1 } };
