import pathlib
p=pathlib.Path("src/main.rs")
t=p.read_text()
# The previous patch added a rayon pool that will panic and abort. We need to make it not abort but still print panic messages.
# The original's panic messages go to stderr via Rust's panic hook, but main continues.
# In rayon, panic in one worker will cause the whole pool to panic and unwind to main, which would abort our program (since we don't catch).
# To mimic, we should use std::thread::spawn with detached threads that panic independently, and main continues after short sleep.
# Let's replace the check block with manual thread spawning.

old = "    // Spawn workers to check charset panic even if empty (original behavior)\n    {\n        let workers_check = if workers == 0 { 1 } else { workers };\n        let pool = rayon::ThreadPoolBuilder::new().num_threads(workers_check).build().unwrap();\n        pool.install(|| {\n            (0..workers_check).into_par_iter().for_each(|_| {\n                password_gen::check(&charset);\n            });\n        });\n        // If charset empty, the above will have panicked in workers, but we still continue to mimic original which after panic still prints Password not found.\n        // In original, panic in workers does not abort main; but our implementation will have panicked and if rayon propagates, it will abort.\n        // To avoid abort, we need to catch panic. We'll use std::panic::catch_unwind\n    }"

new = """    // Mimic original panic behavior for empty charset: spawn workers that panic, but don't abort main
    if charset.is_empty() {
        let workers_check = if workers == 0 { 1 } else { workers };
        let mut handles = Vec::new();
        for i in 0..workers_check {
            let charset_clone = charset.clone();
            let handle = std::thread::Builder::new().name(format!("worker-{}", i+1)).spawn(move || {
                password_gen::check(&charset_clone);
            }).unwrap();
            handles.push(handle);
        }
        // Wait a bit for panics to print, then detach (join with catch)
        for handle in handles {
            let _ = handle.join();
        }
        // After panics, return None to trigger Password not found (original behavior)
        // Note: original also prints Time elapsed after panics, which will be done by caller
        return None;
    }"""

